-- Reconstruir JSON CLOB Modelo 620 en PPFDATOS
SET SERVEROUTPUT ON;
DECLARE
  json   clob;
  stra   clob;
  strb   clob;
  idDatos_  PPFDATOS.IDDATOS%TYPE := {{IDDATOS}};
BEGIN
  stra := '{{JSON_PARTE_A}}';
  strb := '{{JSON_PARTE_B}}';
  json := stra || strb;
  UPDATE PPFDATOS SET JSON = json WHERE IDDATOS = idDatos_;
  DBMS_OUTPUT.put_line('JSON actualizado: '||SQL%ROWCOUNT||' fila(s)');
ROLLBACK;
END;
/
